import sys
import a
import time

def resource_path(relative_path):
        if getattr(sys, "frozen", False) and hasattr(sys, "_MEIPASS"):
            base_path = Path(sys._MEIPASS)
        else:
            base_path = Path(__file__).resolve().parent

        return base_path / relative_path


class Ui_MainWindow(object):
    def fillcombo(self):
        a.city.sort()
        for item in a.city:
            self.comboBox.addItem(item)
    
    def mysignals(self):
        self.pushButton.clicked.connect(self.additem)
        self.comboBox.currentIndexChanged.connect(self.enableadd)

    def enableadd(self):
        self.pushButton.setEnabled(self.comboBox.currentIndex()) 
        

    def additem(self):  
        appid="f2f238852603acca0c878c17215c1d12"
        city=self.comboBox.currentText()
        my_url=f'https://api.openweathermap.org/geo/1.0/direct?q={city}&appid={appid}'
        res=requests.get(url=my_url)
        
        if res.status_code==200:
            data=res.json()
            lat=data[0]['lat']
            lon=data[0]['lon']
            my_url=f'https://api.openweathermap.org/data/2.5/weather?lat={lat}&lon={lon}&appid={appid}'
            res1=requests.get(url=my_url)
         
            if res1.status_code==200:
                data1=res1.json()
                c=data1['main']['temp']-273.15
                t=str(time.ctime(data1['sys']['sunrise']))
                v=str(time.ctime(data1['sys']['sunset']))
                i=str(data1['weather'][0]['description'])
                self.labelTemp.setText(f'{c:.2f}')
                self.labelT.setText(t[-14:-6])
                self.labelQ.setText(v[-14:-6])
                self.labelV.setText(a.weather_dict[i])
                if i in  ["clear sky","few clouds","scattered clouds", "broken clouds","overcast clouds"]:
                    self.label_9.setPixmap(QtGui.QPixmap(str(resource_path("4.png"))))
                elif i in ["light rain","moderate rain","heavy intensity rain","very heavy rain","extreme rain","freezing rain"]:
                    self.label_9.setPixmap(QtGui.QPixmap(str(resource_path("1.png"))))
                elif i in [ "light snow","snow","heavy snow","sleet"]:
                    self.label_9.setPixmap(QtGui.QPixmap(str(resource_path("2.png"))))
                elif i in [  "thunderstorm", "thunderstorm with rain","thunderstorm with heavy rain"]:
                    self.label_9.setPixmap(QtGui.QPixmap(str(resource_path("6.png"))))
                elif i in ["mist","fog"]:
                    self.label_9.setPixmap(QtGui.QPixmap(str(resource_path("3.png"))))
                elif i in ["haze","smoke","dust","sand","tornado"]:
                    self.label_9.setPixmap(QtGui.QPixmap(str(resource_path("5.png"))))
        else:
            print(res.status_code)         

     
    

